<?php
require_once __DIR__ . '/../includes/auth.php'; require_login();
$user=current_user(); $pdo=db(); $errors=[];
$stmt=$pdo->prepare("SELECT id,name FROM categories WHERE (user_id=? OR user_id IS NULL) AND type='expense' ORDER BY name ASC"); $stmt->execute([$user['id']]); $categories=$stmt->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
$name=trim($_POST['name']??''); $categoryId=(int)($_POST['category_id']??0); $amount=(float)($_POST['amount']??0); $period=$_POST['period']??'monthly'; $month=(int)($_POST['month']??date('n')); $year=(int)($_POST['year']??date('Y'));
if($name==='')$errors[]='Nama anggaran wajib diisi.'; if($categoryId<=0)$errors[]='Pilih kategori pengeluaran.'; if($amount<=0)$errors[]='Batas anggaran harus lebih dari 0.'; if(!in_array($period,['monthly','yearly'],true))$errors[]='Periode anggaran tidak valid.'; if($year<2000||$year>2100)$errors[]='Tahun anggaran tidak valid.'; if($month<1||$month>12)$errors[]='Bulan anggaran tidak valid.';
if(!$errors){$check=$pdo->prepare("SELECT id FROM categories WHERE id=? AND (user_id=? OR user_id IS NULL) AND type='expense'");$check->execute([$categoryId,$user['id']]);if(!$check->fetchColumn())$errors[]='Kategori tidak ditemukan atau tidak dapat digunakan.';}
if(!$errors){$stmt=$pdo->prepare('INSERT INTO budgets (user_id,category_id,name,amount,period,month,year) VALUES (?,?,?,?,?,?,?)');$stmt->execute([$user['id'],$categoryId,$name,$amount,$period,$period==='monthly'?$month:null,$year]);header('Location: index.php?success=1');exit;}}
$stmt=$pdo->prepare("SELECT b.*,c.name AS category_name,COALESCE((SELECT SUM(t.amount) FROM transactions t WHERE t.user_id=b.user_id AND t.category_id=b.category_id AND t.type='expense' AND YEAR(t.transaction_date)=b.year AND (b.period='yearly' OR MONTH(t.transaction_date)=b.month)),0) AS spent FROM budgets b LEFT JOIN categories c ON c.id=b.category_id WHERE b.user_id=? ORDER BY b.year DESC,b.month DESC,b.id DESC");$stmt->execute([$user['id']]);$rows=$stmt->fetchAll();
$totalLimit=0;$totalSpent=0;foreach($rows as $r){$totalLimit+=(float)$r['amount'];$totalSpent+=(float)$r['spent'];}
$page_title='Anggaran'; require_once __DIR__ . '/../includes/header.php'; ?>
