etter-spacing:-.3px}.finance-page .alert-error,.finance-page .alert-success{padding:13px 16px;border-radius:10px;margin:0 0 18px;font-size:13px}.finance-page .alert-error{background:#fff1f1;color:#b42318;border:1px solid #ffd7d7}.finance-page .alert-success{background:#ecfdf3;color:#137a43;border:1px solid #c8f2d8}.finance-page .empty{min-height:140px;padding:28px;text-align:center;display:flex;align-items:center;justify-content:center;color:#8b98aa;font-size:13px}.finance-page .inline-form{display:flex;gap:7px;align-items:center;min-width:190px}.finance-page .inline-form input{min-width:105px;min-height:35px;padding:7px 9px;font-size:12px}.finance-page .inline-form button{white-space:nowrap}.finance-page progress{width:112px;height:7px;accent-color:#3b82f6;display:block;margin-top:7px}
