<div class="summary-grid"><div class="summary-box"><span>Total batas anggaran</span><strong>Rp <?=number_format($totalLimit,0,',','.')?></strong></div><div class="summary-box"><span>Total terpakai</span><strong>Rp <?=number_format($totalSpent,0,',','.')?></strong></div><div class="summary-box"><span>Anggaran tersisa</span><strong>Rp <?=number_format(max(0,$totalLimit-$totalSpent),0,',','.')?></strong></div></div>
<section class="finance-card"><div class="card-head"><div><h2>Buat anggaran baru</h2><p>Tentukan kategori, nominal, dan periode anggaran.</p></div></div><div class="card-body"><?php if(!$categories): ?><div class="empty">Belum ada kategori pengeluaran. Tambahkan kategori pengeluaran terlebih dahulu.</div><?php else: ?><form method="post"><div class="form-grid"><div class="form-group"><label for="budget-name">Nama anggaran</label><input id="budget-name" name="name" maxlength="100" placeholder="Contoh: Belanja bulanan" value="<?=htmlspecialchars($_POST['name']??'',ENT_QUOTES,'UTF-8')?>" required></div><div class="form-group"><label for="category-id">Kategori pengeluaran</label><select id="category-id" name="category_id" required><option value="">Pilih kategori</option><?php foreach($categories as $category): ?><option value="<?=(int)$category['id']?>" <?=(int)($_POST['category_id']??0)===(int)$category['id']?'selected':''?>><?=htmlspecialchars($category['name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach; ?></select></div><div class="form-group"><label for="budget-amount">Batas anggaran (Rp)</label><input id="budget-amount" type="number" name="amount" min="1" step="0.01" placeholder="Contoh: 1500000" value="<?=htmlspecialchars($_POST['amount']??'',ENT_QUOTES,'UTF-8')?>" required></div><div class="form-group"><label for="budget-period">Periode</label><select id="budget-period" name="period"><option value="monthly" <?=($_POST['period']??'monthly')==='monthly'?'selected':''?>>Bulanan</option><option value="yearly" <?=($_POST['period']??'')==='yearly'?'selected':''?>>Tahunan</option></select></div><div class="form-group"><label for="budget-month">Bulan (untuk periode bulanan)</label><select id="budget-month" name="month"><?php for($m=1;$m<=12;$m++): ?><option value="<?=$m?>" <?=(int)($_POST['month']??date('n'))===$m?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor; ?></select></div><div class="form-group"><label for="budget-year">Tahun</label><input id="budget-year" type="number" name="year" min="2000" max="2100" value="<?=htmlspecialchars($_POST['year']??date('Y'),ENT_QUOTES,'UTF-8')?>" required></div></div><div class="form-actions"><button class="btn primary" type="submit">＋ Simpan anggaran</button></div></form><?php endif; ?></div></section>
<section class="finance-card"><div class="card-head"><div><h2>Daftar anggaran</h2><p>Pantau pemakaian dan sisa batas anggaran.</p></div></div><?php if(!$rows): ?><div class="empty">Belum ada anggaran. Buat anggaran pertama kamu di atas.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Anggaran</th><th>Kategori</th><th>Periode</th><th>Batas</th><th>Terpakai</th><th>Sisa</th><th>Progres</th></tr></thead><tbody><?php foreach($rows as $row):$limit=(float)$row['amount'];$spent=(float)$row['spent'];$pct=$limit>0?min(100,($spent/$limit)*100):0;$periodLabel=$row['period']==='yearly'?'Tahunan '.$row['year']:date('F',mktime(0,0,0,(int)$row['month'],1)).' '.$row['year']; ?><tr><td><span class="primary-text"><?=htmlspecialchars($row['name'],ENT_QUOTES,'UTF-8')?></span></td><td><?=htmlspecialchars($row['category_name']??'-',ENT_QUOTES,'UTF-8')?></td><td><span class="badge neutral"><?=htmlspecialchars($periodLabel,ENT_QUOTES,'UTF-8')?></span></td><td>Rp <?=number_format($limit,0,',','.')?></td><td>Rp <?=number_format($spent,0,',','.')?></td><td><strong>Rp <?=number_format(max(0,$limit-$spent),0,',','.')?></strong></td><td><strong><?=number_format($pct,0,',','.')?>%</strong><?php if($spent>$limit): ?><span class="muted" style="color:#c24141">Melebihi batas</span><?php endif; ?><div class="progress-track"><div class="progress-fill" style="width:<?=$pct?>%;background:<?=$spent>$limit?'#ef4444':'#3b82f6'?>"></div></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</div><?php require_once __DIR__ . '/../includes/footer.php'; ?>